/// A global whose latent effect reads itself, or a member of its group,
/// may reach itself through the store: its type says `spin`, as FX-26's
/// must (`no_reaching_itself`).
pub fn no_reaching_itself(v: &'static Cv, group: Strings, sc: &'static Scheme) -> &'static Cv {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            let tagcase_ = t;
            match *tagcase_ {
                Ty::TyProc(es, ps, r) => {
                    if (not(string_member_p(str_lit("spin"), es)) && any_p(lambda1(move |n: Str| {
                        string_member_p(string_append(str_lit("g:"), n), es)
                    }), group)) {
                        refuse(v, string_append(str_lit("calling it reads "), string_append(words_of(group), str_lit(": it may reach itself through a global, so its type must say spin"))))
                    } else {
                        v
                    }
                }
                _ => {
                    let other = tagcase_;
                    v
                }
            }
        }
    }
}

/// Whether a definition of one procedure ends however it calls itself, so
/// that its calls of itself need no `spin` (`terminates?`).
pub fn ends_alone_p(v: &'static Cv, name: Str, sc: &'static Scheme, defined: &'static Sexp) -> bool {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            terminates_p(v, kayak_rt::cons(name, kayak_rt::nil()), kayak_rt::cons(t, kayak_rt::nil()), kayak_rt::cons(defined, kayak_rt::nil()))
        }
    }
}

/// A constant's value, of effect `es`: it may read globals, and allocate,
/// and is then made once, at its first use, and kept (C21), which the
/// emitter is told; nothing else, since when it is made is not when
/// FX-26 makes it, where it is defined.
pub fn constant_made(v: &'static Cv, s: &'static St, e: &'static Sexp, es: Strings) -> &'static St {
    if any_p(lambda1(move |x: Str| {
        not((string_eq_p(x, str_lit("spin")) || string_eq_p(x, str_lit("@globals")) || global_atom_p(x) || has_prefix_p(x, str_lit("alloc:"))))
    }), es) {
        refuse(v, string_append(str_lit("a constant whose value has the effect "), string_append(show_effs(es), str_lit(": KFX makes a constant at its first use, so its value may only read globals and allocate"))))
    } else if any_p(lambda1(move |x: Str| {
        has_prefix_p(x, str_lit("alloc:"))
    }), es) {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Lst(xs, file, line, pos) => {
                note_fact(s, file, pos, str_lit("once"))
            }
            _ => {
                let other = tagcase_;
                s
            }
        }
    } else {
        s
    }
}

/// A procedure's lambda against its type; `v` already has its name.
pub fn check_procedure(v: &'static Cv, defined: &'static Sexp, sc: &'static Scheme) -> &'static Cv {
    let (lam, v) = (items(if head_is_p(defined, str_lit("plambda")) {
        third(items(defined))
    } else {
        defined
    }), with_binds(v, kayak_rt::cons(bind(str_lit("%toplambda"), scheme(nil(), ty_unit()), str_lit("yes")), kayak_rt::nil())));
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            let tagcase_ = check_lambda(with_tvars(v, tvars), new_state(), items(second(lam)), cdr(cdr(lam)), t);
            match *tagcase_ {
                Res::Res(u, es, s) => {
                    with_facts(v, st_facts(s))
                }
            }
        }
    }
}

pub fn variants_dt(v: &'static Cv, d: Str) -> List<&'static Dt> {
    let found = find_dt(d, cv_dts(v));
    if null_p(found) {
        refuse(v, string_append(str_lit("no datatype is named "), d))
    } else {
        find_family(d, cv_dts(v))
    }
}

/// A define-rec's members, one by one, each one's facts kept: `group`,
/// those whose calls are recursion (none if the group ends); `names`, all
/// of them, whose reading is reaching itself, ending or not.
pub fn check_members(mut v: &'static Cv, mut bindings: Sexps, mut group: Strings, mut names: Strings) -> &'static Cv {
    loop {
        if null_p(bindings) {
            return v;
        } else {
            let ys = items(car(bindings));
            if procedure_p(third(ys)) {
                (v, bindings) = (check_procedure(no_reaching_itself(at(v, name_of(v, car(ys)), group), names, parse_scheme(v, second(ys))), third(ys), parse_scheme(v, second(ys))), cdr(bindings));
                continue;
            } else {
                return refuse(v, str_lit("a define-rec binds only lambdas"));
            }
        }
    }
}

/// A define-rec: every member in scope in each, and each a lambda.
pub fn check_rec(v: &'static Cv, bindings: Sexps) -> &'static Cv {
    let names = map(lambda1(move |b: &'static Sexp| {
        name_of(v, car(items(b)))
    }), bindings);
    let ends = terminates_p(v, names, map(lambda1(move |b: &'static Sexp| {
        let tagcase_ = parse_scheme(v, second(items(b)));
        match *tagcase_ {
            Scheme::Scheme(tvars, t) => {
                t
            }
        }
    }), bindings), map(lambda1(move |b: &'static Sexp| {
        third(items(b))
    }), bindings));
    let named = with_binds(v, map(lambda1(move |b: &'static Sexp| {
        let ys = items(b);
        global(v, name_of(v, car(ys)), parse_scheme(v, second(ys)))
    }), bindings));
    check_members(named, bindings, if ends {
        nil()
    } else {
        names
    }, names)
}

pub fn global_reads(mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil();
        } else {
            if (string_eq_p(car(es), str_lit("@globals")) || global_atom_p(car(es))) {
                return cons(car(es), global_reads(cdr(es)));
            } else {
                es = cdr(es);
                continue;
            }
        }
    }
}

/// `(define* name type lambda)`: as FX-26 has it, the globals its body
/// reads are found, not written. The body is checked as though the type
/// read every global; the global is then of the type written, its effect
/// with the globals found.
pub fn check_define_star(v: &'static Cv, xs: Sexps) -> &'static Cv {
    let name = name_of(v, second(xs));
    let defined = fourth(xs);
    let v = at(v, name, if ends_alone_p(v, name, parse_scheme(v, third(xs)), defined) {
        nil()
    } else {
        kayak_rt::cons(name, kayak_rt::nil())
    });
    let lam = items(if head_is_p(defined, str_lit("plambda")) {
        third(items(defined))
    } else {
        defined
    });
    if not(procedure_p(defined)) {
        refuse(v, str_lit("a define* is of a lambda"))
    } else {
        let tagcase_ = parse_scheme(v, third(xs));
        match *tagcase_ {
            Scheme::Scheme(tvars, t) => {
                let tagcase_ = t;
                match *tagcase_ {
                    Ty::TyProc(declared, ps, r) => {
                        let wide = ty_proc(effs_union(kayak_rt::cons(str_lit("@globals"), kayak_rt::nil()), declared), ps, r);
                        let named = with_binds(v, kayak_rt::cons(global(v, name, scheme(tvars, wide)), kayak_rt::nil()));
                        let found = lambda_effects(with_tvars(named, tvars), new_state(), items(second(lam)), cdr(cdr(lam)), wide);
                        let es = {
                            let tagcase_ = found;
                            match *tagcase_ {
                                Res::Res(u, es, s) => {
                                    es
                                }
                            }
                        };
                        let fs = {
                            let tagcase_ = found;
                            match *tagcase_ {
                                Res::Res(u, es, s) => {
                                    st_facts(s)
                                }
                            }
                        };
                        if effs_within_p(es, effs_union(kayak_rt::cons(str_lit("@globals"), kayak_rt::nil()), declared)) {
                            with_facts(with_binds(no_reaching_itself(v, kayak_rt::cons(name, kayak_rt::nil()), scheme(tvars, ty_proc(effs_union(global_reads(es), declared), ps, r))), kayak_rt::cons(global(v, name, scheme(tvars, ty_proc(effs_union(global_reads(es), declared), ps, r))), kayak_rt::nil())), fs)
                        } else {
                            refuse(v, string_append(str_lit("a define* whose effect "), string_append(show_effs(es), string_append(str_lit(" is not within "), show_effs(declared)))))
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        refuse(v, str_lit("a define* is of a procedure"))
                    }
                }
            }
        }
    }
}

/// One top-level form, which may add to what the forms after it see.
pub fn check_top(v: &'static Cv, form: &'static Sexp) -> &'static Cv {
    let tagcase_ = form;
    match *tagcase_ {
        Sexp::Str(x) => {
            v
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            let (v, h) = (near(v, src_file, src_line, src_pos), if null_p(xs) {
                str_lit("")
            } else {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(n) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("")
                    }
                }
            });
            if string_eq_p(h, str_lit("define-effect")) {
                with_effdef(v, xs)
            } else if string_eq_p(h, str_lit("define-type")) {
                // Its body read where it stands, used or not: so that one that
                // mentions itself, or names no type, is refused.
                if head_is_p(third(xs), str_lit("moduleof")) {
                    spec_well_formed(v, third(xs));
                    module_type_values(module_scope(v, third(xs), str_lit(""), str_lit("")), third(xs));
                    v
                } else {
                    let name = head_name(v, second(xs));
                    let params = family_params(v, second(xs));
                    let body = parse_type(v, cons(string_append(str_lit("%expanding "), name), params), third(xs));
                    v
                }
            } else if string_eq_p(h, str_lit("define-datatype")) {
                let d = car(variants_dt(v, head_name(v, second(xs))));
                defined_once(v, constructors(d))
            } else if string_eq_p(h, str_lit("define-generative")) {
                defined_once(v, conversions(v, xs))
            } else if string_eq_p(h, str_lit("define")) {
                if not(i64_eq(size(xs), 4i64)) {
                    refuse(v, str_lit("a definition needs a type"))
                } else {
                    let name = name_of(v, second(xs));
                    let sc = parse_scheme(v, third(xs));
                    let v = at(v, name, if ends_alone_p(v, name, sc, fourth(xs)) {
                        nil()
                    } else {
                        kayak_rt::cons(name, kayak_rt::nil())
                    });
                    let v = no_reaching_itself(v, kayak_rt::cons(name, kayak_rt::nil()), sc);
                    let named = with_binds(v, kayak_rt::cons(global(v, name, sc), kayak_rt::nil()));
                    if procedure_p(fourth(xs)) {
                        check_procedure(named, fourth(xs), sc)
                    } else {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tvars, t) => {
                                if null_p(tvars) {
                                    let tagcase_ = check(v, new_state(), fourth(xs), t);
                                    match *tagcase_ {
                                        Res::Res(u, es, s) => {
                                            with_facts(named, st_facts(constant_made(v, s, fourth(xs), es)))
                                        }
                                    }
                                } else {
                                    refuse(v, str_lit("a poly constant: only a procedure may be poly"))
                                }
                            }
                        }
                    }
                }
            } else if string_eq_p(h, str_lit("define-rec")) {
                check_rec(v, cdr(xs))
            } else if string_eq_p(h, str_lit("define*")) {
                check_define_star(v, xs)
            } else {
                let tagcase_ = synth(at(v, str_lit("a top-level expression"), nil()), new_state(), form);
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        with_facts(v, st_facts(if void_p(s, t) {
                            note_fact(s, src_file, src_pos, str_lit("void"))
                        } else {
                            s
                        }))
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = synth(at(v, str_lit("a top-level expression"), nil()), new_state(), form);
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    with_facts(v, st_facts(s))
                }
            }
        }
    }
}

pub fn module_def_p(form: &'static Sexp) -> bool {
    (head_is_p(form, str_lit("define")) && i64_eq(size(items(form)), 3i64) && head_is_p(third(items(form)), str_lit("module")))
}

/// The names of the types and modules `forms` define, one Rust scope's.
pub fn type_level_names(forms: Sexps) -> Strings {
    concat(map(lambda1(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-datatype")) || head_is_p(f, str_lit("define-generative"))) {
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Sym(n) => {
                    the::<Strings>(kayak_rt::cons(n, kayak_rt::nil()))
                }
                Sexp::Lst(ys, fl, ln, ps) => {
                    let tagcase_ = car(ys);
                    match *tagcase_ {
                        Sexp::Sym(n) => {
                            the::<Strings>(kayak_rt::cons(n, kayak_rt::nil()))
                        }
                        _ => {
                            let other = tagcase_;
                            nil()
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    nil()
                }
            }
        } else if module_def_p(f) {
            the::<Strings>(kayak_rt::cons(sym_name(second(items(f))), kayak_rt::nil()))
        } else {
            nil()
        }
    }), forms))
}

/// Each Rust scope's type and module names: the program's, then each module's.
pub fn type_scopes(forms: Sexps) -> List<Strings> {
    cons(type_level_names(forms), concat(map(lambda1(move |f: &'static Sexp| {
        if module_def_p(f) {
            the::<List<Strings>>(kayak_rt::cons(type_level_names(concat(map(lambda1(move |g: &'static Sexp| {
                if head_is_p(g, str_lit("hide")) {
                    cdr(items(g))
                } else {
                    the::<Sexps>(kayak_rt::cons(g, kayak_rt::nil()))
                }
            }), cdr(items(third(items(f))))))), kayak_rt::nil()))
        } else {
            nil()
        }
    }), forms)))
}

/// No type is named as one the generated Rust names: kayak-rt's (`Str`,
/// `List`, ...) and the few of Rust's it writes (`Fn`, `Result`, `Copy`,
/// ...); others of Rust's prelude a program's own type hides.
pub fn type_names_free(v: &'static Cv, forms: Sexps) -> () {
    map(lambda1(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-datatype")) || head_is_p(f, str_lit("define-generative"))) {
            let name = {
                let tagcase_ = second(items(f));
                match *tagcase_ {
                    Sexp::Sym(n) => {
                        n
                    }
                    Sexp::Lst(ys, fl, ln, ps) => {
                        let tagcase_ = car(ys);
                        match *tagcase_ {
                            Sexp::Sym(n) => {
                                n
                            }
                            _ => {
                                let other = tagcase_;
                                str_lit("")
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("")
                    }
                }
            };
            if string_member_p(camel(name), kayak_rt::cons(str_lit("Str"), kayak_rt::cons(str_lit("List"), kayak_rt::cons(str_lit("Cons"), kayak_rt::cons(str_lit("Int"), kayak_rt::cons(str_lit("Tag"), kayak_rt::cons(str_lit("Unwind"), kayak_rt::cons(str_lit("Ref"), kayak_rt::cons(str_lit("FlatArray"), kayak_rt::cons(str_lit("Knot"), kayak_rt::cons(str_lit("Show"), kayak_rt::cons(str_lit("OnceCell"), kayak_rt::cons(str_lit("Fn"), kayak_rt::cons(str_lit("Result"), kayak_rt::cons(str_lit("Ok"), kayak_rt::cons(str_lit("Err"), kayak_rt::cons(str_lit("String"), kayak_rt::cons(str_lit("Copy"), kayak_rt::cons(str_lit("Clone"), kayak_rt::cons(str_lit("Self"), kayak_rt::cons(str_lit("Module"), kayak_rt::nil()))))))))))))))))))))) {
                refuse(v, string_append(str_lit("Rust or kayak-rt has a type "), string_append(camel(name), str_lit(" of its own"))))
            } else {
                ()
            }
        } else {
            ()
        }
    }), forms);
    map(lambda1(move |names: Strings| {
        map(lambda1(move |n: Str| {
            if kfx_name_p(n) {
                ()
            } else {
                refuse(v, string_append(str_lit("a type's or module's name KFX's names are not (C27): "), n))
            }
        }), names);
        if repeated_p(map(&camel, names)) {
            refuse(v, str_lit("two types or modules named alike in Rust (camel-cased, as `point` and `point-`)"))
        } else {
            ()
        }
    }), type_scopes(forms));
    ()
}

// Elaboration. A definition with no type, `(define x e)`, has the type the
// checker finds for `e`; the emitter, which knows no types, is told it, as
// though it had been written. It is never `poly`, and must be known whole.
pub enum Typed {
    Typed(Str, &'static Sexp),
}

pub fn typed(f0: Str, f1: &'static Sexp) -> &'static Typed {
    alloc(Typed::Typed(f0, f1))
}

pub type Typeds = List<&'static Typed>;

pub enum Elab {
    Elab(&'static Cv, Typeds),
}

pub fn elab(f0: &'static Cv, f1: Typeds) -> &'static Elab {
    alloc(Elab::Elab(f0, f1))
}

/// `(define x e)`: `e`'s type found, `x` not in scope in `e` (as FX-26
/// has it, for a lambda too), and the type kept for the emitter.
pub fn check_untyped(v: &'static Cv, form: &'static Sexp) -> &'static Elab {
    let xs = items(form);
    let name = name_of(v, second(xs));
    let v = at(v, name, nil());
    let e = third(xs);
    let tagcase_ = synth(v, new_state(), e);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            let (written, s) = (ty_sexp(v, s, t), if procedure_p(e) {
                s
            } else {
                constant_made(v, s, e, es)
            });
            elab(with_facts(with_binds(v, kayak_rt::cons(global(v, name, scheme(nil(), zonk(s, t))), kayak_rt::nil())), st_facts(s)), kayak_rt::cons(typed(name, written), kayak_rt::nil()))
        }
    }
}

// Modules (CLAUDES_CHOICES.md C19): `(define m (module item ...))` at the
// top level, a Rust `mod`. Its items are a program's definitions, each
// seeing those before it; its types are named `m..t` for the program, so
// that a module's and the program's never meet, and a generative type's
// conversions stay inside. Outside, `m`'s values and types are named `m x`,
// found by `with` and `select`.
pub fn tag_taken_p(tag: Str, ds: Dts) -> bool {
    any_p(lambda1(move |d: &'static Dt| {
        let tagcase_ = d;
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                any_p(lambda1(move |x: &'static Variant| {
                    let tagcase_ = x;
                    match *tagcase_ {
                        Variant::Variant(t, fs) => {
                            string_eq_p(t, tag)
                        }
                    }
                }), vs)
            }
        }
    }), ds)
}

/// A module's types' names, each refused if the program has a type of
/// that name; and the items KFX's modules do not have, refused.
pub fn module_types(mut v: &'static Cv, mut forms: Sexps) -> Strings {
    loop {
        if null_p(forms) {
            return nil();
        } else {
            let f = car(forms);
            if (head_is_p(f, str_lit("define-datatype")) && any_p(lambda1(move |vt: &'static Sexp| {
                tag_taken_p(sym_name(car(items(vt))), cv_dts(v))
            }), cdr(cdr(items(f))))) {
                return refuse(v, str_lit("a module's datatype whose tag another datatype has: KFX's tags name one datatype each"));
            } else if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
                let name = {
                    let tagcase_ = second(items(f));
                    match *tagcase_ {
                        Sexp::Sym(n) => {
                            n
                        }
                        _ => {
                            let other = tagcase_;
                            refuse(v, str_lit("a module's type with parameters, which KFX's modules do not have yet"))
                        }
                    }
                };
                if dt_named_p(name, cv_dts(v)) {
                    return refuse(v, string_append(str_lit("a module's type named as the program's: KFX names them apart, "), name));
                } else {
                    return cons(name, module_types(v, cdr(forms)));
                }
            } else if (head_is_p(f, str_lit("define-effect")) && i64_eq(size(items(f)), 3i64) && escapes_p(parse_effect(v, nil(), third(items(f))))) {
                return refuse(v, str_lit("a module's effect that may abort, which KFX's modules do not have yet"));
            } else if (head_is_p(f, str_lit("hide")) || module_def_p(f)) {
                return refuse(v, string_append(str_lit("an item KFX's modules do not have yet: "), show_sexp(car(items(f)))));
            } else {
                forms = cdr(forms);
                continue;
            }
        }
    }
}

/// A type written in module `m`, its types named as the program names them.
pub fn qualify_type(m: Str, names: Strings, t: &'static Sexp) -> &'static Sexp {
    let tagcase_ = t;
    match *tagcase_ {
        Sexp::Sym(n) => {
            if string_member_p(n, names) {
                sym(string_append(m, string_append(str_lit(".."), n)))
            } else {
                t
            }
        }
        Sexp::Lst(xs, file, line, pos) => {
            lst(map(lambda1(move |x: &'static Sexp| {
                qualify_type(m, names, x)
            }), xs), file, line, pos)
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// A module's types: each `m..t`; and `t` inside it, `m t` outside.
pub fn module_aliases(m: Str, names: Strings, forms: Sexps, inside: bool) -> Aliases {
    concat(map(lambda1(move |f: &'static Sexp| {
        if not((head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype")))) {
            nil()
        } else {
            let xs = items(f);
            let t = sym_name(second(xs));
            let q = string_append(m, string_append(str_lit(".."), t));
            let name = if inside {
                t
            } else {
                string_append(m, string_append(str_lit(" "), t))
            };
            let named = alias(name, nil(), sym(q));
            if head_is_p(f, str_lit("define-type")) {
                the::<Aliases>(kayak_rt::cons(named, kayak_rt::cons(alias(q, nil(), qualify_type(m, names, third(xs))), kayak_rt::nil())))
            } else {
                the::<Aliases>(kayak_rt::cons(named, kayak_rt::nil()))
            }
        }
    }), forms))
}

pub fn module_dts(m: Str, forms: Sexps) -> Dts {
    concat(map(lambda1(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
            the::<Dts>(kayak_rt::cons(dt(string_append(m, string_append(str_lit(".."), sym_name(second(items(f))))), nil(), nil()), kayak_rt::nil()))
        } else {
            nil()
        }
    }), forms))
}

/// A module's generative types' conversions, `up-t` and `down-t`: its
/// items', not in its type, so that outside `m..t` is abstract.
pub fn module_conversions(v: &'static Cv, m: Str, forms: Sexps) -> Binds {
    concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("define-generative")) {
            let xs = items(f);
            let t = sym_name(second(xs));
            let made = ty_data(string_append(m, string_append(str_lit(".."), t)), nil());
            let repr = parse_type(v, nil(), third(xs));
            the::<Binds>(kayak_rt::cons(bind(string_append(str_lit("up-"), t), scheme(nil(), ty_proc(nil(), kayak_rt::cons(repr, kayak_rt::nil()), made)), str_lit("item")), kayak_rt::cons(bind(string_append(str_lit("down-"), t), scheme(nil(), ty_proc(nil(), kayak_rt::cons(made, kayak_rt::nil()), repr)), str_lit("item")), kayak_rt::nil())))
        } else {
            nil()
        }
    }), forms))
}

/// A module's datatypes, their variants read where its types are named.
pub fn module_datatypes(v: &'static Cv, m: Str, forms: Sexps) -> Dts {
    concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("define-datatype")) {
            let tagcase_ = datatype_of(v, cdr(items(f)));
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    the::<Dts>(kayak_rt::cons(dt(string_append(m, string_append(str_lit(".."), n)), ps, vs), kayak_rt::nil()))
                }
            }
        } else {
            nil()
        }
    }), forms))
}

/// A module's effect abbreviations, as `m e`: what each is, as the module
/// read it.
pub fn module_effects(m: Str, forms: Sexps, es: Effdefs) -> Effdefs {
    concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("define-effect")) {
            let name = sym_name(second(items(f)));
            concat(map(lambda1(move |d: &'static Effdef| {
                let tagcase_ = d;
                match *tagcase_ {
                    Effdef::Effdef(n, atoms) => {
                        if string_eq_p(n, name) {
                            the::<Effdefs>(kayak_rt::cons(effdef(string_append(m, string_append(str_lit(" "), n)), atoms), kayak_rt::nil()))
                        } else {
                            nil()
                        }
                    }
                }
            }), es))
        } else {
            nil()
        }
    }), forms))
}

/// The items' values, before the module's mark, as `m x`.
pub fn module_exports(mut m: Str, mut conversions: Strings, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    if string_eq_p(n, str_lit("%module")) {
                        return nil();
                    } else if string_member_p(n, conversions) {
                        bs = cdr(bs);
                        continue;
                    } else {
                        return cons(bind(string_append(m, string_append(str_lit(" "), n)), sc, str_lit("export")), module_exports(m, conversions, cdr(bs)));
                    }
                }
            }
        }
    }
}

pub fn untyped_p(form: &'static Sexp) -> bool {
    (head_is_p(form, str_lit("define")) && i64_eq(size(items(form)), 3i64))
}

/// A module's items, in order: as the program's forms, but that its
/// generative types are made already, and its elaborated types are named
/// `m x`.
pub fn check_items(mut v: &'static Cv, mut m: Str, mut forms: Sexps, mut found: Typeds) -> &'static Elab {
    loop {
        if null_p(forms) {
            return elab(v, found);
        } else if (head_is_p(car(forms), str_lit("define-generative")) || head_is_p(car(forms), str_lit("define-datatype")) || head_is_p(car(forms), str_lit("include"))) {
            forms = cdr(forms);
            continue;
        } else if untyped_p(car(forms)) {
            let tagcase_ = car(forms);
            match *tagcase_ {
                Sexp::Lst(xs, src_file, src_line, src_pos) => {
                    let tagcase_ = check_untyped(near(v, src_file, src_line, src_pos), car(forms));
                    match *tagcase_ {
                        Elab::Elab(v2, more) => {
                            (v, forms, found) = (at(v2, str_lit(""), nil()), cdr(forms), onto(map(lambda1(move |x: &'static Typed| {
                                let tagcase_ = x;
                                match *tagcase_ {
                                    Typed::Typed(n, t) => {
                                        typed(string_append(m, string_append(str_lit(" "), n)), t)
                                    }
                                }
                            }), more), found));
                            continue;
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    forms = cdr(forms);
                    continue;
                }
            }
        } else {
            (v, forms) = (check_top(v, car(forms)), cdr(forms));
            continue;
        }
    }
}

// A module's `(include n)` and `(hide item ...)` (FX-26's): an included
// module's values and types are the module's own, in scope in all its
// items, and in its type unless hidden; a hidden item is the module's, not
// in its type. The module included is one defined at the top level.
/// The items, those of a `hide` among them.
pub fn unhidden(forms: Sexps) -> Sexps {
    concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            the::<Sexps>(kayak_rt::cons(f, kayak_rt::nil()))
        }
    }), forms))
}

/// A module's items, where it includes another: each definition's value
/// found by itself, then fitted to its type, as FX-26 checks such a
/// module's (a literal is an `int` there, a lambda's parameters written),
/// marked `%found`.
pub fn found_alone(forms: Sexps) -> Sexps {
    if not(any_p(lambda1(move |f: &'static Sexp| {
        head_is_p(f, str_lit("include"))
    }), forms)) {
        forms
    } else {
        if any_p(lambda1(move |f: &'static Sexp| {
            head_is_p(f, str_lit("define-rec"))
        }), forms) {
            error(str_lit("kfx: a define-rec in a module that includes another, which KFX's modules do not have yet"))
        } else {
            map(lambda1(move |g: &'static Sexp| {
                if (head_is_p(g, str_lit("define")) && i64_eq(size(items(g)), 4i64)) {
                    let tagcase_ = g;
                    match *tagcase_ {
                        Sexp::Lst(xs, file, line, pos) => {
                            lst(kayak_rt::cons(car(xs), kayak_rt::cons(second(xs), kayak_rt::cons(third(xs), kayak_rt::cons(lst(kayak_rt::cons(sym(str_lit("%found")), kayak_rt::cons(fourth(xs), kayak_rt::nil())), str_lit(""), 0i64, 0i64), kayak_rt::nil())))), file, line, pos)
                        }
                        _ => {
                            let other = tagcase_;
                            g
                        }
                    }
                } else {
                    g
                }
            }), forms)
        }
    }
}

/// The names an item defines: values and types.
pub fn item_names(f: &'static Sexp) -> Strings {
    if (head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*")) || head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative"))) {
        let tagcase_ = second(items(f));
        match *tagcase_ {
            Sexp::Sym(n) => {
                the::<Strings>(kayak_rt::cons(n, kayak_rt::nil()))
            }
            _ => {
                let other = tagcase_;
                nil()
            }
        }
    } else if head_is_p(f, str_lit("define-rec")) {
        map(lambda1(move |b: &'static Sexp| {
            sym_name(car(items(b)))
        }), cdr(items(f)))
    } else {
        nil()
    }
}

/// The names hidden items define, and the values of modules a `hide`
/// includes.
pub fn hidden_names(forms: Sexps) -> Strings {
    concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            concat(map(lambda1(move |g: &'static Sexp| {
                if (head_is_p(g, str_lit("define-generative")) || head_is_p(g, str_lit("define-datatype"))) {
                    error(str_lit("kfx: a hidden generative type or datatype, which KFX's modules do not have yet"))
                } else {
                    item_names(g)
                }
            }), cdr(items(f))))
        } else {
            nil()
        }
    }), forms))
}

/// The modules `forms` include, each defined at the top level.
pub fn included(v: &'static Cv, forms: Sexps) -> Strings {
    concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("include")) {
            let n = name_of(v, second(items(f)));
            if (null_p(find_bind(n, cv_binds(v))) || not({
                let tagcase_ = car(find_bind(n, cv_binds(v)));
                match *tagcase_ {
                    Bind::Bind(x, sc, w) => {
                        string_eq_p(w, str_lit("module"))
                    }
                }
            })) {
                refuse(v, string_append(str_lit("KFX includes a module defined at the top level, by its name: "), n))
            } else {
                the::<Strings>(kayak_rt::cons(n, kayak_rt::nil()))
            }
        } else {
            nil()
        }
    }), forms))
}

/// The modules included not in a `hide`: their types are the module's.
pub fn unhidden_includes(v: &'static Cv, written: Sexps) -> Strings {
    included(v, concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            nil()
        } else {
            the::<Sexps>(kayak_rt::cons(f, kayak_rt::nil()))
        }
    }), written)))
}

/// Module `n`'s types, opened, as module `m`'s: `m t`.
pub fn renamed_aliases(n: Str, m: Str, r#as: Aliases) -> Aliases {
    map(lambda1(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(t, ps, body) => {
                alias(string_append(m, string_append(str_lit(" "), t)), ps, body)
            }
        }
    }), r#as)
}

/// A module's exported types, those hidden dropped.
pub fn without_aliases(hidden: Strings, m: Str, r#as: Aliases) -> Aliases {
    concat(map(lambda1(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(t, ps, body) => {
                if string_member_p(after_prefix(t, string_append(m, str_lit(" "))), hidden) {
                    nil()
                } else {
                    the::<Aliases>(kayak_rt::cons(a, kayak_rt::nil()))
                }
            }
        }
    }), r#as))
}

pub fn check_module(v: &'static Cv, form: &'static Sexp) -> &'static Elab {
    let xs = items(form);
    let m = name_of(v, second(xs));
    let v = at(v, m, nil());
    let made = {
        let tagcase_ = global(v, m, scheme(nil(), ty_unit()));
        match *tagcase_ {
            Bind::Bind(n, sc, r#where) => {
                bind(n, sc, str_lit("module"))
            }
        }
    };
    let written = cdr(items(third(xs)));
    let forms = found_alone(unhidden(written));
    let hidden = onto(hidden_names(written), map(lambda1(move |b: &'static Bind| {
        let tagcase_ = b;
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                n
            }
        }
    }), concat(map(lambda1(move |n: Str| {
        opened_binds(n, cv_binds(v))
    }), included(v, concat(map(lambda1(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            nil()
        }
    }), written)))))));
    let includes = included(v, forms);
    let names = module_types(v, forms);
    let given = onto(concat(map(&item_names, forms)), onto(map(lambda1(move |b: &'static Bind| {
        let tagcase_ = b;
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                n
            }
        }
    }), concat(map(lambda1(move |n: Str| {
        opened_binds(n, cv_binds(v))
    }), includes))), map(lambda1(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(n, ps, b) => {
                n
            }
        }
    }), concat(map(lambda1(move |n: Str| {
        opened_aliases(n, cv_aliases(v))
    }), includes)))));
    let v = if repeated_p(given) {
        refuse(v, str_lit("a name defined twice in this module, its own or included"))
    } else {
        v
    };
    let typed = {
        let tagcase_ = v;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
                cv(bind_onto(concat(map(lambda1(move |n: Str| {
                    opened_binds(n, bs)
                }), includes)), cons(bind(str_lit("%module"), scheme(nil(), ty_unit()), m), bs)), onto(module_dts(m, forms), ds), onto(module_aliases(m, names, forms, true), onto(concat(map(lambda1(move |n: Str| {
                    opened_aliases(n, r#as)
                }), includes)), r#as)), es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let datatypes = module_datatypes(typed, m, forms);
    let typed = {
        let tagcase_ = typed;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
                cv(bs, onto(datatypes, ds), r#as, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let conversions = module_conversions(typed, m, forms);
    let inner = defined_once(typed, onto(conversions, concat(map(&constructors, datatypes))));
    let tagcase_ = check_items(inner, m, forms, nil());
    match *tagcase_ {
        Elab::Elab(done, found) => {
            let tagcase_ = done;
            match *tagcase_ {
                Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
                    elab(cv(cons(made, bind_onto(module_exports(m, onto(hidden, map(lambda1(move |b: &'static Bind| {
                        let tagcase_ = b;
                        match *tagcase_ {
                            Bind::Bind(n, sc, w) => {
                                n
                            }
                        }
                    }), conversions)), bs), cv_binds(v))), ds, onto(without_aliases(hidden, m, module_aliases(m, names, forms, false)), onto(concat(map(lambda1(move |n: Str| {
                        renamed_aliases(n, m, opened_aliases(n, cv_aliases(v)))
                    }), unhidden_includes(v, written))), cv_aliases(v))), onto(module_effects(m, forms, es), cv_effdefs(v)), here, group, file, line, fs, tv, at), found)
                }
            }
        }
    }
}

/// The forms in order; `found`, the types elaborated so far.
pub fn check_tops(mut v: &'static Cv, mut forms: Sexps, mut found: Typeds) -> &'static Elab {
    loop {
        if null_p(forms) {
            return elab(v, found);
        } else if module_def_p(car(forms)) {
            let tagcase_ = car(forms);
            match *tagcase_ {
                Sexp::Lst(xs, src_file, src_line, src_pos) => {
                    let tagcase_ = check_module(near(v, src_file, src_line, src_pos), car(forms));
                    match *tagcase_ {
                        Elab::Elab(v2, more) => {
                            (v, forms, found) = (at(v2, str_lit(""), nil()), cdr(forms), onto(more, found));
                            continue;
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    forms = cdr(forms);
                    continue;
                }
            }
        } else if untyped_p(car(forms)) {
            let tagcase_ = car(forms);
            match *tagcase_ {
                Sexp::Lst(xs, src_file, src_line, src_pos) => {
                    let tagcase_ = check_untyped(near(v, src_file, src_line, src_pos), car(forms));
                    match *tagcase_ {
                        Elab::Elab(v2, more) => {
                            (v, forms, found) = (at(v2, str_lit(""), nil()), cdr(forms), onto(more, found));
                            continue;
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    forms = cdr(forms);
                    continue;
                }
            }
        } else {
            (v, forms) = (check_top(v, car(forms)), cdr(forms));
            continue;
        }
    }
}

// What checking a program gives the emitter: the types of the definitions
// written with none, and the facts.
pub enum Verdict {
    Verdict(Typeds, Facts),
}

pub fn verdict(f0: Typeds, f1: Facts) -> &'static Verdict {
    alloc(Verdict::Verdict(f0, f1))
}

pub fn verdict_typeds(x: &'static Verdict) -> Typeds {
    let tagcase_ = x;
    match *tagcase_ {
        Verdict::Verdict(ts, fs) => {
            ts
        }
    }
}

pub fn verdict_facts(x: &'static Verdict) -> Facts {
    let tagcase_ = x;
    match *tagcase_ {
        Verdict::Verdict(ts, fs) => {
            fs
        }
    }
}

/// Every form, in order; the first error stops the compiler. What it gives
/// is the types of the definitions written with none.
pub fn check_program(forms: Sexps) -> &'static Verdict {
    let empty = cv(nil(), nil(), nil(), nil(), str_lit("a type"), nil(), str_lit("the program"), 0i64, nil(), nil(), 0i64);
    let start = cv(nil(), nil(), declare_types(empty, forms, nil()), nil(), str_lit("a type"), nil(), str_lit("the program"), 0i64, nil(), nil(), 0i64);
    let types = type_names_free(start, forms);
    let named = {
        let tagcase_ = start;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
                cv(bs, datatype_names(start, forms, nil()), r#as, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let typed = {
        let tagcase_ = named;
        match *tagcase_ {
            Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
                cv(bs, declare_datatypes(named, forms, nil()), r#as, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let v = with_binds(typed, prim_binds(typed));
    let tagcase_ = check_tops(v, forms, nil());
    match *tagcase_ {
        Elab::Elab(done, found) => {
            verdict(found, cv_facts(done))
        }
    }
}

